// Some portions generated by Claude
import assert from "node:assert/strict";
import test from "node:test";
import {
  facetCombinable,
  facetCounts,
  facetIndex,
  facetModel,
  RANGE_VALUE,
  TYPE_FACET_ID,
} from "../../../main/frontend/graph-explorer/graph-facets.ts";
import { NODE_KIND_FACET_ID } from "../../../main/frontend/graph-explorer/graph-filters.ts";
import { UNTYPED_IRI_TYPE } from "../../../main/frontend/graph-explorer/graph-visuals.ts";
import {
  BLANK_VALUE_ID,
  exactMatchQueries,
  exactMatchQuery,
  generatedFacetQuery,
} from "../../../main/frontend/graph-explorer/facet-queries.ts";
import { LONG_LITERAL_VALUE_ID } from "../../../main/frontend/graph-explorer/facet-value-ids.ts";
import { NO_MATCH_VALUE } from "../../../main/frontend/graph-explorer/graph-facets.ts";

// Inside one filter the selected values match any of them (union) unless the filter is switched to all of them
// (intersection); filters still combine with each other as before (every filter must match).
const SPEAKS = "urn:speaks";
const AGE = "urn:age";
const XSD = "http://www.w3.org/2001/XMLSchema#";
const person = { id: "urn:Person", label: "Person" };
const author = { id: "urn:Author", label: "Author" };
const robot = { id: "urn:Robot", label: "Robot" };
const iri = (id, types) => ({ id, label: id.slice(4), kind: "iri", types });
const language = (id) => ({ id, label: id.slice(4), kind: "iri" });
const number = (value) => ({ id: `"${value}"`, label: String(value), termValue: String(value), kind: "literal", datatype: `${XSD}integer` });
const edge = (source, predicate, target) => ({ id: `${source} ${predicate} ${target}`, source, predicate, label: predicate.slice(4), target });

const people = [
  iri("urn:ann", [person, author]), iri("urn:ben", [person]), iri("urn:cy", [person, author]), iri("urn:dan", [robot]),
  iri("urn:eve", []),
];
const languages = ["urn:en", "urn:nb", "urn:de", "urn:fr"].map(language);
const ages = [number(20), number(30), number(40), number(50)];
const speaks = { "urn:ann": ["urn:en", "urn:nb"], "urn:ben": ["urn:en"], "urn:cy": ["urn:nb", "urn:de", "urn:fr"], "urn:dan": ["urn:en", "urn:nb", "urn:de"] };
const edges = [
  ...Object.entries(speaks).flatMap(([who, spoken]) => spoken.map((target) => edge(who, SPEAKS, target))),
  edge("urn:ann", AGE, '"20"'), edge("urn:ben", AGE, '"30"'), edge("urn:cy", AGE, '"40"'), edge("urn:dan", AGE, '"50"'),
];
const input = {
  nodes: people,
  edges,
  nodeById: new Map([...people, ...languages, ...ages].map((node) => [node.id, node])),
  typesOf: (node) => (node.types?.length ? node.types : [UNTYPED_IRI_TYPE]),
  hiddenPredicates: new Set(),
};
const model = (selection, modes) => facetModel({ ...input, selection, modes });
const matches = (result) => [...result.matches].sort();
const counts = (result, id) =>
  Object.fromEntries((result.facets.find((facet) => facet.id === id)?.values ?? []).map((value) => [value.label, value.count]));
const all = (...ids) => new Map(ids.map((id) => [id, "all"]));

test("a filter set to all matches only the nodes that have every selected value", () => {
  const selection = new Map([[SPEAKS, new Set(["urn:en", "urn:nb"])]]);
  assert.deepEqual(matches(model(selection)), ["urn:ann", "urn:ben", "urn:cy", "urn:dan"], "any: one of them is enough");
  assert.deepEqual(matches(model(selection, all(SPEAKS))), ["urn:ann", "urn:dan"], "all: both are needed");
  assert.deepEqual(matches(model(selection, all("urn:other"))), matches(model(selection)), "only the switched filter changes");
});

test("a filter set to all still combines with the other filters, which keep their own mode", () => {
  const selection = new Map([[SPEAKS, new Set(["urn:en", "urn:nb"])], [TYPE_FACET_ID, new Set(["urn:Person", "urn:Robot"])]]);
  assert.deepEqual(matches(model(selection, all(SPEAKS))), ["urn:ann", "urn:dan"]);
  assert.deepEqual(matches(model(selection, all(SPEAKS, TYPE_FACET_ID))), [], "nobody is both a person and a robot");
  assert.deepEqual(
    matches(model(new Map([[TYPE_FACET_ID, new Set(["urn:Person", "urn:Author"])]]), all(TYPE_FACET_ID))),
    ["urn:ann", "urn:cy"],
  );
});

test("the counts of a filter set to all narrow with every value picked", () => {
  // Any: a filter's counts ignore its own selection, so every language stays on offer.
  assert.deepEqual(counts(model(new Map([[SPEAKS, new Set(["urn:en"])]])), SPEAKS), { en: 3, nb: 3, de: 2, fr: 1 });
  // All: each count is how many of the matches also have the value, i.e. how many would remain after adding it.
  assert.deepEqual(counts(model(new Map([[SPEAKS, new Set(["urn:en"])]]), all(SPEAKS)), SPEAKS), { en: 3, nb: 2, de: 1 });
  assert.deepEqual(
    counts(model(new Map([[SPEAKS, new Set(["urn:en", "urn:nb"])]]), all(SPEAKS)), SPEAKS),
    { en: 2, nb: 2, de: 1 },
    "values none of the matches have drop out",
  );
});

test("a selected value stays listed when an all filter leaves nothing to match", () => {
  const result = model(new Map([[SPEAKS, new Set(["urn:en", "urn:fr"])]]), all(SPEAKS));
  assert.equal(result.matches.size, 0);
  assert.deepEqual(counts(result, SPEAKS), { en: 0, fr: 0 });
});

test("no type and a type together match nothing when the type filter is set to all", () => {
  const selection = new Map([[TYPE_FACET_ID, new Set([UNTYPED_IRI_TYPE.id, "urn:Person"])]]);
  assert.deepEqual(matches(model(selection)), ["urn:ann", "urn:ben", "urn:cy", "urn:eve"]);
  assert.deepEqual(matches(model(selection, all(TYPE_FACET_ID))), []);
});

test("only type filters and property filters without a range can be switched", () => {
  assert.equal(facetCombinable(TYPE_FACET_ID, false), true);
  assert.equal(facetCombinable(SPEAKS, false), true);
  assert.equal(facetCombinable(AGE, true), false, "a range matches a value inside it");
  assert.equal(facetCombinable(NODE_KIND_FACET_ID, false), false, "a node has one kind");
  assert.equal(facetCombinable("__literal_datatype__", false), false);
  assert.equal(facetCombinable("__literal_language__", false), false);
});

test("filters that cannot be switched ignore a mode", () => {
  const kinds = new Map([[NODE_KIND_FACET_ID, new Set(["iri", "literal"])]]);
  assert.deepEqual(matches(model(kinds, all(NODE_KIND_FACET_ID))), matches(model(kinds)));
  const index = facetIndex({ ...input, selection: new Map() });
  const ranged = new Map([[AGE, new Set([RANGE_VALUE])]]);
  const ranges = new Map([[AGE, { from: "25", to: "45" }]]);
  assert.deepEqual(
    matches(facetCounts(index, ranged, { ranges, modes: all(AGE) })),
    matches(facetCounts(index, ranged, { ranges })),
    "a range selects the nodes with a value inside it",
  );
});

test("a node whose values were not all loaded matches an all filter once the server confirms it", () => {
  const cy = { predicates: new Map([[SPEAKS, { values: ["urn:nb"], complete: false }]]), predicatesComplete: true };
  const index = facetIndex({ ...input, nodes: [people[2]], edges: [], repositoryValues: (id) => (id === "urn:cy" ? cy : undefined) });
  const selection = new Map([[SPEAKS, new Set(["urn:nb", "urn:de"])]]);
  assert.equal(facetCounts(index, selection, { modes: all(SPEAKS) }).matches.size, 0, "de is not among the loaded values");
  const confirmed = new Map([[SPEAKS, new Set(["urn:cy"])]]);
  assert.deepEqual(matches(facetCounts(index, selection, { modes: all(SPEAKS), confirmed })), ["urn:cy"]);
});

test("the server check asks once per value for an all filter and keeps the nodes in every answer", () => {
  const ids = ["urn:a", "urn:b"];
  assert.deepEqual(exactMatchQueries(ids, SPEAKS, { values: ["urn:en", "urn:nb"] }), [exactMatchQuery(ids, SPEAKS, { values: ["urn:en", "urn:nb"] })]);
  assert.deepEqual(exactMatchQueries(ids, SPEAKS, { values: ["urn:en"], mode: "all" }), [exactMatchQuery(ids, SPEAKS, { values: ["urn:en"] })]);
  assert.deepEqual(
    exactMatchQueries(ids, SPEAKS, { values: ["urn:en", BLANK_VALUE_ID], mode: "all" }, "all"),
    [exactMatchQuery(ids, SPEAKS, { values: ["urn:en"] }, "all"), exactMatchQuery(ids, SPEAKS, { values: [BLANK_VALUE_ID] }, "all")],
  );
  const range = { range: { kind: "number", from: "1", to: "2" } };
  assert.deepEqual(exactMatchQueries(ids, AGE, range), [exactMatchQuery(ids, AGE, range)]);
});

test("the generated query asks for every value of an all filter, each on its own", () => {
  const selection = new Map([[SPEAKS, new Set(["urn:en", "urn:nb"])]]);
  const any = generatedFacetQuery(selection, { wikidata: false });
  assert.equal(generatedFacetQuery(selection, { wikidata: false, modes: new Map() }), any, "any is what it was");
  assert.match(any, /VALUES \?facetValue0 \{ <urn:en> <urn:nb> \}/);
  const both = generatedFacetQuery(selection, { wikidata: false, modes: all(SPEAKS) });
  assert.doesNotMatch(both, /VALUES \?facetValue0/);
  assert.match(both, /\?focus <urn:speaks> <urn:en> \./);
  assert.match(both, /\?focus <urn:speaks> <urn:nb> \./);
  const single = new Map([[SPEAKS, new Set(["urn:en"])]]);
  assert.equal(generatedFacetQuery(single, { wikidata: false, modes: all(SPEAKS) }), generatedFacetQuery(single, { wikidata: false }),
    "one value is the same either way");
});

test("an all filter on every graph lets each value come from its own graph", () => {
  const both = generatedFacetQuery(new Map([[SPEAKS, new Set(["urn:en", "urn:nb"])]]), { wikidata: false, scope: "all", modes: all(SPEAKS) });
  assert.match(both, /GRAPH \?__facet0_0 \{ \?focus <urn:speaks> <urn:en> \. \}/);
  assert.match(both, /GRAPH \?__facet0_1 \{ \?focus <urn:speaks> <urn:nb> \. \}/);
});

test("merged values of an all filter become conditions instead of being left out", () => {
  const selection = new Map([[SPEAKS, new Set(["urn:en", BLANK_VALUE_ID, LONG_LITERAL_VALUE_ID])]]);
  const query = generatedFacetQuery(selection, { wikidata: false, modes: all(SPEAKS) });
  assert.match(query, /\?focus <urn:speaks> \?facetValue0_1 \.\s+FILTER\(isBlank\(\?facetValue0_1\)\)/);
  assert.match(query, /FILTER\(isLiteral\(\?facetValue0_2\) && STRLEN\(STR\(\?facetValue0_2\)\) > 1024\)/);
  const nothing = generatedFacetQuery(new Map([[SPEAKS, new Set(["urn:en", NO_MATCH_VALUE])]]), { wikidata: false, modes: all(SPEAKS) });
  assert.match(nothing, /FILTER\(false\)/);
});

test("the generated query needs every selected type of an all type filter", () => {
  const types = new Map([[TYPE_FACET_ID, new Set(["urn:Person", "urn:Author"])]]);
  const query = generatedFacetQuery(types, { wikidata: false, modes: all(TYPE_FACET_ID) });
  assert.match(query, /FILTER\(EXISTS \{ [^}]*<urn:Person> \. \} && EXISTS \{ [^}]*<urn:Author> \. \}\)/);
  const untyped = new Map([[TYPE_FACET_ID, new Set([UNTYPED_IRI_TYPE.id, "urn:Person"])]]);
  assert.match(generatedFacetQuery(untyped, { wikidata: false, modes: all(TYPE_FACET_ID) }), /FILTER\(false\)/);
});

test("the server check matches the merged long text value next to the others", () => {
  const ids = ["urn:a"];
  const long = exactMatchQuery(ids, SPEAKS, { values: [LONG_LITERAL_VALUE_ID] });
  assert.doesNotMatch(long, /FILTER\(false\)/);
  assert.match(long, /FILTER\(\(isLiteral\(\?o\) && STRLEN\(STR\(\?o\)\) > 1024\)\)/);
  const mixed = exactMatchQuery(ids, SPEAKS, { values: ["urn:en", BLANK_VALUE_ID, LONG_LITERAL_VALUE_ID] });
  assert.match(mixed, /FILTER\(isBlank\(\?o\) \|\| \(isLiteral\(\?o\) && STRLEN\(STR\(\?o\)\) > 1024\) \|\| sameTerm\(\?o, <urn:en>\)\)/);
  for (const query of exactMatchQueries(ids, SPEAKS, { values: ["urn:en", LONG_LITERAL_VALUE_ID], mode: "all" }))
    assert.doesNotMatch(query, /FILTER\(false\)/, "each value of an all filter can be found");
});

test("the generated query of an any filter keeps its merged values", () => {
  const blank = generatedFacetQuery(new Map([[SPEAKS, new Set([BLANK_VALUE_ID])]]), { wikidata: false });
  assert.doesNotMatch(blank, /FILTER\(false\)/);
  assert.match(blank, /FILTER\(isBlank\(\?facetValue0\)\)/);
  const mixed = generatedFacetQuery(new Map([[SPEAKS, new Set(["urn:en", BLANK_VALUE_ID, LONG_LITERAL_VALUE_ID])]]), { wikidata: false });
  assert.match(mixed,
    /FILTER\(isBlank\(\?facetValue0\) \|\| \(isLiteral\(\?facetValue0\) && STRLEN\(STR\(\?facetValue0\)\) > 1024\) \|\| sameTerm\(\?facetValue0, <urn:en>\)\)/);
  assert.match(generatedFacetQuery(new Map([[SPEAKS, new Set(["urn:en", "urn:nb"])]]), { wikidata: false }),
    /VALUES \?facetValue0 \{ <urn:en> <urn:nb> \}/, "plain values stay a VALUES list");
});
